// Eingabe der Runtime: { query?: string, unread_only?: boolean, limit?: number }
const incoming = $input.first().json;
const inp = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
const terms = [];
if (typeof inp.query === 'string' && inp.query.trim() !== '') terms.push(inp.query.trim());
if (inp.unread_only === true) terms.push('is:unread');
const limit = Number.isInteger(inp.limit) ? Math.max(1, Math.min(50, inp.limit)) : 20;
return [{ json: { q: terms.join(' '), limit } }];

// Auf genau die vier erlaubten Angaben je Treffer zusammenschneiden. NIE den Volltext.
const headers = $input.all().map((item, i) => {
  const m = item.json || {};
  const payloadHeaders = (m.payload && m.payload.headers) || [];
  const h = (name) => {
    const hit = payloadHeaders.find((x) => (x.name || '').toLowerCase() === name);
    return hit ? hit.value : '';
  };
  return {
    id: String(m.id || m.messageId || ('msg_' + (i + 1))),
    subject: m.subject || h('subject') || '(kein Betreff)',
    from: m.from || h('from') || '(unbekannt)',
    date: m.date || h('date') || m.internalDate || '',
    summary: (m.snippet || '').toString().slice(0, 240),
    unread: Array.isArray(m.labelIds) ? m.labelIds.includes('UNREAD') : (m.unread === true)
  };
});
return [{ json: { messages: headers, count: headers.length } }];
